function ModulePanel({title,sub,children,action}:{title:string;sub:string;children:React.ReactNode;action?:React.ReactNode}){return <section className="panel modulepanel"><div className="panelhead"><div><h3>{title}</h3><p>{sub}</p></div>{action}</div>{children}</section>}
function CalendarModule({organizationId,userId,role,clients,projects,toast}:ModuleProps&{clients:ClientOption[];projects:ProjectOption[]}){
 const [events,setEvents]=useState<any[]>([]),[title,setTitle]=useState(''),[starts,setStarts]=useState(new Date(Date.now()+3600000).toISOString().slice(0,16)),[kind,setKind]=useState('meeting'),[description,setDescription]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const cloud=Boolean(supabase&&organizationId&&userId); const canEdit=['owner','admin','manager','member'].includes(role);
 const loadEvents=useCallback(async()=>{if(!cloud||!supabase)return;setBusy(true);const {data,error}=await supabase.from('calendar_events').select('id,title,description,event_type,starts_at,ends_at,location,project_id,client_id').eq('organization_id',organizationId!).order('starts_at',{ascending:true}).limit(100);if(error)setError(error.message);else setEvents(data??[]);setBusy(false)},[cloud,organizationId]);
 useEffect(()=>{void loadEvents()},[loadEvents]);
 async function addEvent(e:React.FormEvent){e.preventDefault();if(!supabase||!organizationId||!userId){setError('Sign in and connect a workspace to save calendar events.');return}setBusy(true);setError('');const {error}=await supabase.from('calendar_events').insert({organization_id:organizationId,created_by:userId,title:title.trim(),description,event_type:kind,starts_at:new Date(starts).toISOString()});setBusy(false);if(error){setError(error.message);return}setTitle('');setDescription('');toast('Calendar event created');void loadEvents()}
 async function removeEvent(id:string){if(!supabase||!organizationId||!window.confirm('Delete this calendar event?'))return;const {error}=await supabase.from('calendar_events').delete().eq('id',id).eq('organization_id',organizationId);if(error){setError(error.message);return}setEvents(v=>v.filter(x=>x.id!==id));toast('Event deleted')}
 return <div className="modulegrid"><ModulePanel title="Upcoming schedule" sub="Meetings, deadlines, reviews and production milestones.">{error&&<p className="moduleerror" role="alert">{error}</p>}{busy&&<p className="modulehint">Syncing calendar…</p>}{!events.length&&!busy&&<p className="empty-state">No events yet. Add your first meeting or milestone.</p>}{events.map(ev=><div className="module-row" key={ev.id}><div className="module-date"><b>{new Date(ev.starts_at).toLocaleDateString('en-IN',{day:'2-digit'})}</b><small>{new Date(ev.starts_at).toLocaleDateString('en-IN',{month:'short'})}</small></div><div className="module-row-main"><b>{ev.title}</b><small>{new Date(ev.starts_at).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'})} · {ev.event_type}</small>{ev.description&&<p>{ev.description}</p>}</div>{canEdit&&<button className="secondary" onClick={()=>void removeEvent(ev.id)}>Delete</button>}</div>)}</ModulePanel><ModulePanel title="Add to calendar" sub="Create a workspace event."><form className="module-form" onSubmit={addEvent}><label className="field"><span>Event title</span><input value={title} onChange={e=>setTitle(e.target.value)} required placeholder="Client review / production day"/></label><label className="field"><span>Type</span><select value={kind} onChange={e=>setKind(e.target.value)}><option value="meeting">Meeting</option><option value="deadline">Deadline</option><option value="milestone">Milestone</option><option value="review">Review</option><option value="production">Production</option></select></label><label className="field"><span>Date and time</span><input type="datetime-local" value={starts} onChange={e=>setStarts(e.target.value)} required/></label><label className="field"><span>Notes</span><textarea value={description} onChange={e=>setDescription(e.target.value)} rows={3}/></label><button className="primary" disabled={busy||!title.trim()} onClick={()=>{}}>Create event</button><p className="modulehint">Events are stored in your agency workspace.</p></form></ModulePanel></div>
}
function FinanceModule({organizationId,userId,role,clients,toast}:ModuleProps&{clients:ClientOption[]}){
 const [invoices,setInvoices]=useState<any[]>([]),[items,setItems]=useState<any[]>([]),[clientId,setClientId]=useState(''),[invoiceNo,setInvoiceNo]=useState(''),[issueDate,setIssueDate]=useState(new Date().toISOString().slice(0,10)),[dueDate,setDueDate]=useState(''),[description,setDescription]=useState('Creative services'),[qty,setQty]=useState('1'),[price,setPrice]=useState('0'),[gst,setGst]=useState('18'),[gstMode,setGstMode]=useState('cgst_sgst'),[discount,setDiscount]=useState('0'),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const cloud=Boolean(supabase&&organizationId&&userId);const canManage=['owner','admin','manager'].includes(role);
 const loadInvoices=useCallback(async()=>{if(!cloud||!supabase)return;setBusy(true);const {data,error}=await supabase.from('invoices').select('id,invoice_number,status,issue_date,due_date,currency,gst_rate,discount_amount,client_id,clients(company_name),invoice_items(quantity,unit_price,description),invoice_payments(amount)').eq('organization_id',organizationId!).order('created_at',{ascending:false});if(error)setError(error.message);else setInvoices(data??[]);setBusy(false)},[cloud,organizationId]);
 useEffect(()=>{void loadInvoices()},[loadInvoices]);
 const subtotal=Number(qty||0)*Number(price||0),tax=gstMode==='none'?0:Math.max(0,subtotal-Number(discount||0))*Number(gst||0)/100,total=Math.max(0,subtotal-Number(discount||0))+tax;
 async function createInvoice(e:React.FormEvent){e.preventDefault();if(!supabase||!organizationId||!userId){setError('Connect and sign in to a Supabase workspace before creating live invoices.');return}if(!clientId){setError('Choose a client first.');return}setBusy(true);setError('');const no=invoiceNo.trim()||`P7-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`;const {error:invoiceError}=await supabase.rpc('create_invoice_draft',{p_organization_id:organizationId,p_client_id:clientId,p_invoice_number:no,p_issue_date:issueDate,p_due_date:dueDate||null,p_gst_rate:Number(gst),p_gst_mode:gstMode,p_discount_amount:Number(discount),p_description:description.trim(),p_quantity:Number(qty),p_unit_price:Number(price)});if(invoiceError){setError(invoiceError.message);setBusy(false);return}setInvoiceNo('');setDescription('Creative services');setQty('1');setPrice('0');setBusy(false);toast('Draft invoice created');void loadInvoices()}
 async function updateStatus(id:string,status:string){if(!supabase||!organizationId)return;const {error}=await supabase.from('invoices').update({status}).eq('id',id).eq('organization_id',organizationId);if(error){setError(error.message);return}toast('Invoice status updated');void loadInvoices()}
 async function printInvoice(inv:any){
  if(!supabase||!organizationId){setError('Connect to the workspace to print a live invoice.');return}
  const w=window.open('','_blank','width=900,height=700');if(!w){setError('Allow pop-ups to print the invoice.');return}
  const {data:settings}=await supabase.from('workspace_settings').select('*').eq('organization_id',organizationId).maybeSingle();
  const esc=(v:any)=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]??c));
  const rows=(inv.invoice_items??[]).map((it:any,i:number)=>`<tr><td>${i+1}</td><td>${esc(it.description)}</td><td>₹${Number(it.unit_price).toLocaleString('en-IN',{minimumFractionDigits:2})}</td><td>${Number(it.quantity)}</td><td>₹${(Number(it.quantity)*Number(it.unit_price)).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr>`).join('');
  const sub=(inv.invoice_items??[]).reduce((a:number,it:any)=>a+Number(it.quantity)*Number(it.unit_price),0);const taxable=Math.max(0,sub-Number(inv.discount_amount??0));const tax=inv.gst_mode==='none'?0:taxable*Number(inv.gst_rate??0)/100;const total=taxable+tax;const paid=(inv.invoice_payments??[]).reduce((a:number,p:any)=>a+Number(p.amount),0);
  const taxRows=inv.gst_mode==='cgst_sgst'?`<tr><td>CGST (${Number(inv.gst_rate)/2}%)</td><td>₹${(tax/2).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td>SGST (${Number(inv.gst_rate)/2}%)</td><td>₹${(tax/2).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr>`:inv.gst_mode==='igst'?`<tr><td>IGST (${Number(inv.gst_rate)}%)</td><td>₹${tax.toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr>`:'';
  w.document.write(`<!doctype html><html><head><title>${esc(inv.invoice_number)}</title><meta charset="utf-8"><style>body{font:13px Arial,sans-serif;color:#191919;margin:38px}header{display:flex;justify-content:space-between;border-bottom:2px solid #ef3c22;padding-bottom:18px}h1{font-size:28px;letter-spacing:2px;margin:0}h2{font-size:14px;margin:0 0 8px}p{line-height:1.6;margin:3px 0}.meta{color:#666;font-size:11px}table{width:100%;border-collapse:collapse;margin-top:24px}th{background:#151515;color:#fff;text-align:left}th,td{padding:10px;border-bottom:1px solid #ddd}td:last-child,th:last-child{text-align:right}.totals{margin:20px 0 20px auto;width:300px}.totals td{border:0;padding:5px}.totals tr:last-child{font-size:17px;font-weight:bold;border-top:2px solid #111}.columns{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:25px}.foot{border-top:1px solid #ddd;margin-top:35px;padding-top:15px;color:#666;font-size:10px}@media print{body{margin:18mm}button{display:none}}</style></head><body><header><div><h2>${esc(settings?.legal_name||'PARALLEL SEVEN')}</h2><p>${esc(settings?.address||'')}</p><p>${esc(settings?.billing_email||'')} ${esc(settings?.phone||'')}</p><p>${settings?.gstin?'GSTIN: '+esc(settings.gstin):''}</p></div><div><h1>INVOICE</h1><p>Invoice no: ${esc(inv.invoice_number)}</p><p>Issue date: ${esc(inv.issue_date)}</p><p>Due date: ${esc(inv.due_date||'—')}</p><p>Status: ${esc(inv.status)}</p></div></header><div class="columns"><div><h2>BILL TO</h2><p>${esc(inv.clients?.company_name||'Client')}</p><p>${esc(clients.find(c=>String(c.id)===String(inv.client_id))?.name||'')}</p></div><div><h2>PAYMENT DETAILS</h2><p>${esc(settings?.bank_name||'')}</p><p>${esc(settings?.bank_branch||'')}</p><p>Account name: ${esc(settings?.account_name||'')}</p><p>Account number: ${esc(settings?.account_number||'')}</p><p>IFSC: ${esc(settings?.ifsc_code||'')}</p></div></div><table><thead><tr><th>ST.</th><th>DESCRIPTION</th><th>PRICE</th><th>QTY.</th><th>TOTAL</th></tr></thead><tbody>${rows}</tbody></table><table class="totals"><tr><td>Subtotal</td><td>₹${sub.toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td>Discount</td><td>−₹${Number(inv.discount_amount??0).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr>${taxRows}<tr><td>Total</td><td>₹${total.toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td>Paid</td><td>₹${paid.toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr><tr><td>Balance</td><td>₹${Math.max(0,total-paid).toLocaleString('en-IN',{minimumFractionDigits:2})}</td></tr></table><div class="columns"><div><h2>NOTES</h2><p>${esc(inv.notes||'')}</p><p>${esc(settings?.invoice_footer||'Thank you for your business.')}</p></div><div><h2>AUTHORISED SIGNATORY</h2><p style="margin-top:45px">${esc(settings?.signature_name||settings?.legal_name||'')}</p></div></div><div class="foot">${esc(settings?.website||'')} · ${esc(settings?.phone||'')} · ${esc(settings?.billing_email||'')}</div><script>window.onload=()=>window.print()</script></body></html>`);w.document.close();
 }
 async function recordPayment(inv:any){const raw=window.prompt(`Payment amount for ${inv.invoice_number} (INR)`);if(raw===null)return;const amount=Number(raw);if(!Number.isFinite(amount)||amount<=0){setError('Enter a valid positive payment amount.');return}if(!supabase||!organizationId||!userId)return;const {error}=await supabase.from('invoice_payments').insert({organization_id:organizationId,invoice_id:inv.id,amount,recorded_by:userId,payment_date:new Date().toISOString().slice(0,10)});if(error){setError(error.message);return}const paid=(inv.invoice_payments??[]).reduce((a:number,p:any)=>a+Number(p.amount),0)+amount;const sub=(inv.invoice_items??[]).reduce((a:number,i:any)=>a+Number(i.quantity)*Number(i.unit_price),0);const taxable=Math.max(0,sub-Number(inv.discount_amount??0));const due=taxable+(inv.gst_mode==='none'?0:taxable*Number(inv.gst_rate??0)/100);await updateStatus(inv.id,paid>=due?'paid':'partially_paid');toast('Payment recorded')}
 const paidTotal=invoices.reduce((sum,inv)=>sum+(inv.invoice_payments??[]).reduce((a:number,p:any)=>a+Number(p.amount),0),0);
 return <div className="modulegrid"><div className="module-stats"><Stat title="Invoices" value={String(invoices.length).padStart(2,'0')} sub="In this workspace" icon={<CreditCard size={17}/>}/><Stat title="Drafts" value={String(invoices.filter(i=>i.status==='draft').length).padStart(2,'0')} sub="Not yet sent" icon={<Pencil size={17}/>}/><Stat title="Payments received" value={money(paidTotal)} sub="Recorded payments" icon={<CheckCircle2 size={17}/>}/></div><ModulePanel title="Invoice register" sub="Drafts, sent invoices and payment tracking.">{error&&<p className="moduleerror" role="alert">{error}</p>}{busy&&<p className="modulehint">Syncing finance records…</p>}{!invoices.length&&!busy&&<p className="empty-state">No invoices yet. Create a draft using the form.</p>}{invoices.map(inv=><div className="module-row invoice-row" key={inv.id}><div className="module-row-main"><b>{inv.invoice_number} · {inv.clients?.company_name??'Client'}</b><small>Issued {inv.issue_date}{inv.due_date?` · Due ${inv.due_date}`:''} · GST {inv.gst_rate}%</small><p>{(inv.invoice_items??[]).map((i:any)=>`${i.description} × ${i.quantity}`).join(', ')||'No line items'} · {money((inv.invoice_items??[]).reduce((a:number,i:any)=>a+Number(i.quantity)*Number(i.unit_price),0))}</p><small>Paid: {money((inv.invoice_payments??[]).reduce((a:number,p:any)=>a+Number(p.amount),0))}</small></div><span className="tag">{inv.status}</span><div className="rowactions"><button className="secondary" onClick={()=>void printInvoice(inv)}>Print / PDF</button>{canManage&&<><select aria-label="Invoice status" value={inv.status} onChange={e=>void updateStatus(inv.id,e.target.value)}>{['draft','sent','partially_paid','paid','overdue','cancelled'].map(s=><option key={s}>{s}</option>)}</select><button className="secondary" onClick={()=>void recordPayment(inv)}>Record payment</button></>}</div></div>)}</ModulePanel><ModulePanel title="Create invoice" sub="Add a client, line item and tax rate to start a draft."><form className="module-form" onSubmit={createInvoice}><label className="field"><span>Client</span><select value={clientId} onChange={e=>setClientId(e.target.value)} required><option value="">Select a client</option>{clients.map(c=><option key={String(c.id)} value={String(c.id)}>{c.company}</option>)}</select></label><label className="field"><span>Invoice number (optional)</span><input value={invoiceNo} onChange={e=>setInvoiceNo(e.target.value)} placeholder="Auto-generate if blank"/></label><label className="field"><span>Issue date</span><input type="date" value={issueDate} onChange={e=>setIssueDate(e.target.value)} required/></label><label className="field"><span>Due date</span><input type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label><label className="field"><span>Description</span><input value={description} onChange={e=>setDescription(e.target.value)} required placeholder="Creative services"/></label><div className="module-two"><label className="field"><span>Quantity</span><input type="number" min="0.01" step="0.01" value={qty} onChange={e=>setQty(e.target.value)} required/></label><label className="field"><span>Unit price (INR)</span><input type="number" min="0" step="0.01" value={price} onChange={e=>setPrice(e.target.value)} required/></label></div><div className="module-two"><label className="field"><span>GST %</span><input type="number" min="0" max="100" step="0.01" value={gst} onChange={e=>setGst(e.target.value)} required/></label><label className="field"><span>GST treatment</span><select value={gstMode} onChange={e=>setGstMode(e.target.value)}><option value="cgst_sgst">CGST + SGST</option><option value="igst">IGST</option><option value="none">No GST</option></select></label><label className="field"><span>Discount (INR)</span><input type="number" min="0" step="0.01" value={discount} onChange={e=>setDiscount(e.target.value)} required/></label></div><div className="invoice-total"><span>Subtotal</span><b>{money(subtotal)}</b><span>Tax</span><b>{money(tax)}</b><span>Total</span><strong>{money(total)}</strong></div><button className="primary" disabled={busy||!clientId||!description.trim()}>Create draft invoice</button><p className="modulehint">This module stores draft invoices and recorded payments. Validate GST treatment and invoice particulars with your accountant before issuing a tax invoice.</p></form></ModulePanel></div>
}
function SettingsModule({organizationId,role,toast}:ModuleProps){
 const [settings,setSettings]=useState<any>({legal_name:'Parallel Seven',billing_email:'',phone:'',website:'',address:'',gstin:'',invoice_prefix:'P7',default_gst_rate:18,default_currency:'INR',bank_name:'',bank_branch:'',account_name:'',account_number:'',ifsc_code:'',signature_name:'',invoice_footer:'Thank you for your business.'}),[busy,setBusy]=useState(false),[error,setError]=useState('');const cloud=Boolean(supabase&&organizationId);const canEdit=['owner','admin'].includes(role);
 useEffect(()=>{let cancelled=false;async function load(){if(!cloud||!supabase)return;const {data,error}=await supabase.from('workspace_settings').select('*').eq('organization_id',organizationId!).maybeSingle();if(cancelled)return;if(error){setError(error.message);return}if(data)setSettings(data)}void load();return()=>{cancelled=true}},[cloud,organizationId]);
 async function save(e:React.FormEvent){e.preventDefault();if(!supabase||!organizationId){setError('Settings need a connected workspace.');return}setBusy(true);setError('');const payload={organization_id:organizationId,...settings,default_gst_rate:Number(settings.default_gst_rate),updated_at:new Date().toISOString()};const {error}=await supabase.from('workspace_settings').upsert(payload,{onConflict:'organization_id'});setBusy(false);if(error){setError(error.message);return}toast('Workspace settings saved')}
 const update=(key:string,value:any)=>setSettings((v:any)=>({...v,[key]:value}));
 return <div className="modulegrid"><ModulePanel title="Workspace profile" sub="Business identity and billing defaults."><form className="module-form" onSubmit={save}>{error&&<p className="moduleerror" role="alert">{error}</p>}{[['legal_name','Legal / business name'],['billing_email','Billing email'],['phone','Phone'],['website','Website'],['gstin','GSTIN'],['invoice_prefix','Invoice prefix'],['default_currency','Default currency'],['bank_name','Bank name'],['bank_branch','Bank branch'],['account_name','Account name'],['account_number','Account number'],['ifsc_code','IFSC code'],['signature_name','Signatory name'],['invoice_footer','Invoice footer']].map(([key,label])=><label className="field" key={key}><span>{label}</span><input value={settings[key]} onChange={e=>update(key,e.target.value)} disabled={!canEdit} type={key==='billing_email'?'email':'text'}/></label>)}<label className="field"><span>Business address</span><textarea rows={3} value={settings.address} onChange={e=>update('address',e.target.value)} disabled={!canEdit}/></label><label className="field"><span>Default GST rate (%)</span><input type="number" min="0" max="100" step="0.01" value={settings.default_gst_rate} onChange={e=>update('default_gst_rate',e.target.value)} disabled={!canEdit}/></label>{canEdit&&<button className="primary" disabled={busy}>{busy?'Saving…':'Save settings'}</button>}<p className="modulehint">Role: {role}. Settings are scoped to the active agency workspace.</p></form></ModulePanel><ModulePanel title="Security & access" sub="Current session and workspace role."><div className="settings-summary"><div><small>Active workspace</small><b>Parallel Seven Agency OS</b></div><div><small>Your role</small><b>{role}</b></div><div><small>Data isolation</small><b>Supabase row-level security</b></div><div><small>Session security</small><b>Supabase Auth</b></div></div><p className="modulehint">Team invitations and role management require a dedicated invite flow; do not share accounts between staff or clients.</p></ModulePanel></div>
}

function AutomationModule({organizationId,userId,role,toast}:ModuleProps){
 const definitions=[{name:'New lead follow-up',event_key:'lead_created',description:'Create a follow-up task when a lead is added.',conditions:{},actions:[{type:'create_task',title:'Follow up with new lead'}]},{name:'Deadline nudge',event_key:'task_deadline',description:'Flag tasks due within the next 24 hours.',conditions:{hours_before:24},actions:[{type:'notify_owner'}]},{name:'Client approval reminder',event_key:'approval_pending',description:'Remind the project owner when feedback is pending.',conditions:{},actions:[{type:'notify_owner'}]}];
 const [rules,setRules]=useState<any[]>(definitions.map(d=>({...d,id:d.event_key,is_enabled:false}))),[busy,setBusy]=useState(false),[error,setError]=useState('');const cloud=Boolean(supabase&&organizationId&&userId);const canManage=['owner','admin','manager'].includes(role);
 const loadRules=useCallback(async()=>{if(!cloud||!supabase)return;setBusy(true);const {data,error}=await supabase.from('automation_rules').select('*').eq('organization_id',organizationId!).order('created_at');if(error){setError(error.message);setBusy(false);return}if(data?.length)setRules(data.map((x:any)=>({...x,description:definitions.find(d=>d.event_key===x.event_key)?.description??x.name})));else{const rows=definitions.map(d=>({...d,organization_id:organizationId,created_by:userId,is_enabled:false}));const {data:created,error:insertError}=await supabase.from('automation_rules').insert(rows).select('*');if(insertError)setError(insertError.message);else if(created?.length)setRules(created.map((x:any)=>({...x,description:definitions.find(d=>d.event_key===x.event_key)?.description??x.name})));}setBusy(false)},[cloud,organizationId,userId]);
 useEffect(()=>{void loadRules()},[loadRules]);
 async function toggle(rule:any){if(!canManage)return;const enabled=!rule.is_enabled;if(cloud&&supabase){const {error}=await supabase.from('automation_rules').update({is_enabled:enabled}).eq('id',rule.id).eq('organization_id',organizationId!);if(error){setError(error.message);return}}setRules(v=>v.map(r=>r.id===rule.id?{...r,is_enabled:enabled}:r));toast(enabled?'Rule enabled':'Rule disabled')}
 return <div className="autopage"><section className="hero smallhero"><div><div className="eyebrow lime"><Workflow size={14}/> WORKFLOW CONFIGURATION</div><h2>Make repeatable work <em>consistent.</em></h2><p>Store and manage automation rule settings for this workspace.</p></div></section><ModulePanel title="Automation rules" sub="These rules are saved as configuration. Event execution and email delivery require a separate worker or scheduled function.">{error&&<p className="moduleerror" role="alert">{error}</p>}{busy&&<p className="modulehint">Syncing automation rules…</p>}{rules.map(r=><div className="autorow" key={r.event_key}><div className="autoicon"><Workflow size={17}/></div><div><b>{r.name}</b><p>{r.description}</p><small>{r.event_key.replaceAll('_',' ')}</small></div><button aria-label={`${r.is_enabled?'Disable':'Enable'} ${r.name}`} disabled={!canManage||busy} className={`toggle ${r.is_enabled?'on':''}`} onClick={()=>void toggle(r)}><i/></button></div>)}<p className="modulehint">{cloud?'Rule configuration syncs to Supabase.':'Demo mode: rule changes are local until Supabase is configured.'} Only owners, admins and managers can change rules.</p></ModulePanel></div>
}


function TeamAccessModule({organizationId,userId,role,clients,toast}:{organizationId:string;userId:string;role:string;clients:Client[];toast:(s:string)=>void}){
 const [email,setEmail]=useState(''),[inviteRole,setInviteRole]=useState('member'),[clientId,setClientId]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[inviteUrl,setInviteUrl]=useState('');
 const canInvite=role==='owner'||role==='admin';
 async function createInvite(e:FormEvent<HTMLFormElement>){
  e.preventDefault();if(!supabase||!canInvite)return;
  setBusy(true);setError('');setInviteUrl('');
  const result=await supabase.rpc('create_workspace_invitation',{p_organization_id:organizationId,p_email:email.trim().toLowerCase(),p_role:inviteRole,p_client_id:inviteRole==='client'?clientId:null});
  setBusy(false);
  if(result.error){setError(result.error.message);return}
  const data:any=result.data;const token=Array.isArray(data)?data[0]?.invitation_token:data?.invitation_token;
  if(!token){setError('Invitation created but no invitation token was returned.');return}
  const url=new URL(window.location.origin+window.location.pathname);url.searchParams.set('invite',String(token));
  setInviteUrl(url.toString());toast('Invitation link created. Share it with the invited person.');
 }
 return <section className="panel team-access"><PanelHead title="Invite your team" sub="Add people to this workspace without creating separate login systems."/>
 {!canInvite?<div className="auth-footnote">Only workspace owners and admins can invite members.</div>:<form className="team-invite-form" onSubmit={createInvite}>
  <label className="auth-field"><span>Member email</span><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required placeholder="teammate@company.com"/></label>
  <label className="auth-field"><span>Access role</span><select value={inviteRole} onChange={e=>setInviteRole(e.target.value)}><option value="member">Staff / Member</option><option value="manager">Manager</option><option value="admin">Admin</option><option value="client">Client</option></select></label>
  {inviteRole==='client'&&<label className="auth-field"><span>Link to client record</span><select value={clientId} onChange={e=>setClientId(e.target.value)} required><option value="">Choose client</option>{clients.map(c=><option key={c.id} value={String(c.id)}>{c.company} — {c.name}</option>)}</select></label>}
  {error&&<div className="auth-error" role="alert">{error}</div>}
  <button className="primary" type="submit" disabled={busy}>{busy?'Creating invite…':'Create invitation link'}</button>
  {inviteUrl&&<div className="invite-link-result"><b>Share this secure link</b><p>It expires in 7 days and only works for {email.trim().toLowerCase()}. Ask the recipient to sign in or create an account with that exact email.</p><input readOnly value={inviteUrl} aria-label="Invitation link"/><button className="primary" type="button" onClick={()=>{void navigator.clipboard.writeText(inviteUrl).then(()=>toast('Invitation link copied')).catch(()=>setError('Copy failed. Select and copy the link manually.'))}}>Copy invitation link</button></div>}
 </form>}
 <div className="auth-footnote">Invitations are email-bound, expire after seven days, and assign access only after the invited person signs in with the matching email. This creates a shareable link; automatic email delivery is not configured yet.</div>
 </section>
}
